L["huntgood.hunts.notebookcover.bone.description"] = "Rawhide stretched taut over a frame and shut with two carved bone toggles. Creaks in the cold."
L["huntgood.hunts.notebookcover.bone.name"] = "Bone & Rawhide"
L["huntgood.hunts.notebookcover.brasscase.description"] = "A brass case engraved with a leaping fish over the reeds, with a latch that clicks like it means it."
L["huntgood.hunts.notebookcover.brasscase.name"] = "Brass Hunter's Case"
L["huntgood.hunts.notebookcover.canvas.description"] = "Plain khaki canvas, stencilled with a number nobody remembers assigning. Fits a coat pocket, just."
L["huntgood.hunts.notebookcover.canvas.name"] = "Canvas Field Pad"
L["huntgood.hunts.notebookcover.fiveseal.description"] = "Black leather with five wax seals pressed into it, one for every set of hunts there is. Nobody fakes this one."
L["huntgood.hunts.notebookcover.fiveseal.name"] = "Five-Set Seal"
L["huntgood.hunts.notebookcover.kraft.description"] = "Brown paper rubbed with beeswax until it shrugs off rain. Tied with twine, because buttons fall off."
L["huntgood.hunts.notebookcover.kraft.name"] = "Waxed Kraft"
L["huntgood.hunts.notebookcover.lacquer.description"] = "Layer upon layer of red lacquer, polished until it holds a reflection, with a gilt carp swimming in it."
L["huntgood.hunts.notebookcover.lacquer.name"] = "Lacquered Red"
L["huntgood.hunts.notebookcover.leather.description"] = "Worn brown leather, gone soft at the corners from a season in a coat pocket."
L["huntgood.hunts.notebookcover.leather.name"] = "Saddle Leather"
L["huntgood.hunts.notebookcover.maplinen.description"] = "A hand-drawn map on linen, the trail dotted in red and an X where somebody swears the big one lives."
L["huntgood.hunts.notebookcover.maplinen.name"] = "Map Linen"
L["huntgood.hunts.notebookcover.oilcloth.description"] = "Stiff oiled canvas that sheds the rain, and most of the fish slime."
L["huntgood.hunts.notebookcover.oilcloth.name"] = "Oilcloth"
L["huntgood.hunts.notebookcover.pathfinder.description"] = "Soft calfskin pressed with a compass rose. Handed to anglers who saw a whole set of hunts through to the end."
L["huntgood.hunts.notebookcover.pathfinder.name"] = "Pathfinder's Calf"
L["huntgood.hunts.notebookcover.planks.description"] = "Thin planks strapped together with leather and brass buckles. Doubles as a cutting board in a pinch."
L["huntgood.hunts.notebookcover.planks.name"] = "Bound Planks"
L["huntgood.hunts.notebookcover.scrimshaw.description"] = "An old ivory panel scratched with a ship and a fish by some sailor with a long voyage and a sharp knife."
L["huntgood.hunts.notebookcover.scrimshaw.name"] = "Scrimshaw Panel"
L["huntgood.hunts.notebookcover.shagreen.description"] = "Ray skin, pebbled like frost, with the pale star at its centre the old makers always kept."
L["huntgood.hunts.notebookcover.shagreen.name"] = "Stingray Shagreen"
L["huntgood.hunts.notebookcover.snakeskin.description"] = "A long swamp snake’s skin, still patterned with the diamonds it hunted by. Cool to the touch, always."
L["huntgood.hunts.notebookcover.snakeskin.name"] = "Snakeskin"
L["huntgood.hunts.notebookcover.tartan.description"] = "Thick green-and-navy wool with a red line through it. Warm hands, damp pages, no regrets."
L["huntgood.hunts.notebookcover.tartan.name"] = "Tartan Wool"
L["huntgood.hunts.notebookcover.tooled.description"] = "Dark leather tooled with reeds and leaping fish, by someone with a sharp knife and a long winter."
L["huntgood.hunts.notebookcover.tooled.name"] = "Tooled Leather"
L["huntgood.hunts.notebookcover.trophycase.description"] = "A dark wood case with a glass front, and behind the glass a fish cast in gold. Opens like a cabinet."
L["huntgood.hunts.notebookcover.trophycase.name"] = "Gilded Trophy Case"
L["huntgood.hunts.notebookcover.verdigris.description"] = "Copper corners and a copper clasp, gone green in the sea air. It was bright once, briefly."
L["huntgood.hunts.notebookcover.verdigris.name"] = "Verdigris"
L["huntgood.hunts.notebookcover.wagersilk.description"] = "Purple silk brocade woven with coins and fish, a red sash across it. Given to anglers who keep winning the house’s bets."
L["huntgood.hunts.notebookcover.wagersilk.name"] = "Winner's Brocade"
L["huntgood.hunts.soundset.nightwatch.description"] = "A low bell for the night watch, a lantern humming and an owl who has seen every catch you ever made."
L["huntgood.hunts.soundset.nightwatch.name"] = "Night Watch"
L["huntgood.hunts.trackerframe.bounty.description"] = "Nailed up at the dock house, edges curling. The fish on it has a price, and the price is going up."
L["huntgood.hunts.trackerframe.bounty.name"] = "Bounty Poster"
L["huntgood.hunts.trackerframe.inkwash.description"] = "A sheet of paper written in blue ink, the wash run a little, like a page that caught the spray."
L["huntgood.hunts.trackerframe.inkwash.name"] = "Ink Wash"
L["huntgood.hunts.trackerframe.mapscrap.description"] = "A corner torn off a hunting map: a dotted trail, a compass, and somebody’s coffee ring."
L["huntgood.hunts.trackerframe.mapscrap.name"] = "Map Scrap"
L["huntgood.hunts.trackerframe.none.description"] = "Only the lines themselves, with nothing drawn around them."
L["huntgood.hunts.trackerframe.none.name"] = "No Frame"
L["huntgood.hunts.trackerframe.slate.description"] = "A slate in a rope-bound frame, chalked fresh each morning and smudged by noon."
L["huntgood.hunts.trackerframe.slate.name"] = "Chalk Slate"
L["huntgood.hunts.trackerframe.spyglass.description"] = "Navy enamel between two brass rails, the eyepiece at the corner turned toward the next hunt."
L["huntgood.hunts.trackerframe.spyglass.name"] = "Spyglass Rim"
L["huntgood.hunts.trackerframe.wagerribbon.description"] = "A purple silk ribbon with a gold fringe, for anglers who keep beating the house at its own wagers."
L["huntgood.hunts.trackerframe.wagerribbon.name"] = "Winner's Ribbon"
L["huntgood.hunts.trackerframe.waxseal.description"] = "Parchment with a red rule down its margin and a wax seal pressed in the corner, as if the list were official."
L["huntgood.hunts.trackerframe.waxseal.name"] = "Wax Seal"
